import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button, Form, FormGroup, Label, Input } from 'reactstrap';

const ContractModal = ({ isOpen, toggle, email, refreshProposals, initialProposal }) => {
    const [formData, setFormData] = useState({
        goodName: '',
        goodDetail: '',
        goodRequire: '',
        term: '',
        paymentMethod: '',
        pay: '',
        photoUrl: null, // 이미지 파일
    });
    const [previewImage, setPreviewImage] = useState(null); // 이미지 미리보기 URL

    useEffect(() => {
        if (initialProposal) {
            setFormData({
                goodName: initialProposal.goodName,
                goodDetail: initialProposal.goodDetail,
                goodRequire: initialProposal.goodRequire,
                term: initialProposal.term,
                paymentMethod: initialProposal.payWay,
                pay: initialProposal.pay,
                photoUrl: null, // 이미지 파일은 null로 초기화
            });
            setPreviewImage(`http://localhost:8080/uploads/${initialProposal.photoUrl}`);
        } else {
            setFormData({
                goodName: '',
                goodDetail: '',
                goodRequire: '',
                term: '',
                paymentMethod: '',
                pay: '',
                photoUrl: null,
            });
            setPreviewImage(null);
        }
    }, [initialProposal]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({
            ...formData,
            [name]: value,
        });
    };

    const handleImageChange = (e) => {
        const file = e.target.files[0];
        setFormData({
            ...formData,
            photoUrl: file,
        });
        setPreviewImage(URL.createObjectURL(file)); // 이미지 미리보기 URL 생성
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        const method = initialProposal ? 'PUT' : 'POST';
        const url = initialProposal
            ? `http://localhost:8080/api/sendProposal/${initialProposal.id}`
            : 'http://localhost:8080/api/sendProposal';

        const form = new FormData();
        form.append('fromId', email);
        form.append('toId', initialProposal ? initialProposal.toId : '');
        form.append('goodName', formData.goodName);
        form.append('goodDetail', formData.goodDetail);
        form.append('goodRequire', formData.goodRequire);
        form.append('term', formData.term);
        form.append('payWay', formData.paymentMethod);
        form.append('pay', formData.pay);

        if (formData.photoUrl) {
            form.append('photoUrl', formData.photoUrl); // 새로운 이미지 파일 추가
        } else if (initialProposal) {
            form.append('photoUrl', initialProposal.photoUrl); // 기존 이미지 URL 유지
        }

        try {
            const response = await fetch(url, {
                method,
                body: form,
            });
            const data = await response.json();
            console.log('Proposal saved:', data);
            refreshProposals();
            toggle();
        } catch (error) {
            console.error('Error:', error);
        }
    };

    return (
        <Modal isOpen={isOpen} toggle={toggle}>
            <ModalHeader toggle={toggle}>{initialProposal ? '제안서 수정' : '새 제안서 추가'}</ModalHeader>
            <ModalBody>
                <Form onSubmit={handleSubmit}>
                    <FormGroup>
                        <Label for="goodName">상품명</Label>
                        <Input
                            type="text"
                            name="goodName"
                            id="goodName"
                            value={formData.goodName}
                            onChange={handleChange}
                            required
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="goodDetail">상품 상세</Label>
                        <Input
                            type="textarea"
                            name="goodDetail"
                            id="goodDetail"
                            value={formData.goodDetail}
                            onChange={handleChange}
                            required
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="goodRequire">요구 사항</Label>
                        <Input
                            type="textarea"
                            name="goodRequire"
                            id="goodRequire"
                            value={formData.goodRequire}
                            onChange={handleChange}
                            required
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="term">기간</Label>
                        <Input
                            type="text"
                            name="term"
                            id="term"
                            value={formData.term}
                            onChange={handleChange}
                            required
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="paymentMethod">지급 방법</Label>
                        <Input
                            type="select"
                            name="paymentMethod"
                            id="paymentMethod"
                            value={formData.paymentMethod}
                            onChange={handleChange}
                            required
                        >
                            <option value="">선택하세요</option>
                            <option value="분할 지급">분할 지급</option>
                            <option value="선불">선불</option>
                            <option value="후불">후불</option>
                        </Input>
                    </FormGroup>
                    <FormGroup>
                        <Label for="pay">금액</Label>
                        <Input
                            type="number"
                            name="pay"
                            id="pay"
                            value={formData.pay}
                            onChange={handleChange}
                            required
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="photoUrl">이미지</Label>
                        <Input
                            type="file"
                            name="photoUrl"
                            id="photoUrl"
                            onChange={handleImageChange}
                            accept="image/*"
                        />
                        {previewImage && (
                            <div>
                                <img
                                    src={previewImage}
                                    alt="미리보기"
                                    style={{ marginTop: '10px', maxWidth: '100%' }}
                                />
                            </div>
                        )}
                    </FormGroup>
                    <Button type="submit" color="primary">
                        {initialProposal ? '수정 완료' : '추가'}
                    </Button>
                </Form>
            </ModalBody>
            <ModalFooter>
                <Button color="secondary" onClick={toggle}>
                    취소
                </Button>
            </ModalFooter>
        </Modal>
    );
};

export default ContractModal;
